</style></head><body><div class="w">
<h1>✂️ Editor de Reels com IA</h1>
<p class="sub">Mande o <b>vídeo que você gravou</b> (falando do seu produto ou serviço) e a IA devolve um <b>Reel pronto para o Instagram</b>: corta as pausas e os "né", "é", "tipo", põe <b>legenda animada</b> com a palavra falada acesa, <b>frase de impacto</b> no topo, <b>tópicos</b>, trilha baixinha e o seu <b>@ no final</b>.</p>
<div class="passos"><div><b>1. Grave</b>em pé, falando, até 1min30</div><div><b>2. Envie</b>e conte o que é</div><div><b>3. A IA edita</b>uns 2 minutos</div><div><b>4. Poste</b>vídeo + legenda prontos</div></div>

<div class="card"><h2>1. O vídeo</h2>
  <p class="sub">MP4 ou MOV do celular, até 120 MB. Grave em pé (9:16); se for deitado, a IA põe em pé com fundo desfocado.</p>
  <div><button class="btn sec" type="button" id="ex">🎬 Usar vídeo de exemplo</button></div>
  <div class="drop" id="drop"><b>📤 Toque para escolher o vídeo</b>ou arraste aqui</div>
  <input type="file" id="arq" accept="video/*" hidden>
  <video id="prev" controls playsinline hidden></video>
  <div class="barra" id="barra" hidden><i></i></div>
  <p class="sub" id="info">Nenhum vídeo ainda.</p>
</div>

<form class="card" id="form"><h2>2. Sobre o vídeo</h2>
  <div class="duas">
    <div><label for="tipo">Tipo</label><select id="tipo"><option value="imovel">🏠 Imóvel</option><option value="produto" selected>🛍️ Produto</option><option value="comida">🍔 Restaurante / comida</option><option value="veiculo">🚗 Carro ou moto</option><option value="servico">🧰 Serviço</option><option value="evento">🎉 Evento</option><option value="outro">✨ Outro</option></select></div>
    <div><label for="marca">Nome do negócio <small>(vai no final)</small></label><input type="text" id="marca" maxlength="50" placeholder="Ex.: Imobiliária Vista Alta"></div>
  </div>
  <label for="titulo">O que aparece no vídeo *</label><input type="text" id="titulo" maxlength="90" placeholder="Ex.: Apartamento 3 quartos com varanda" required>
  <label for="detalhes">Detalhes <small>(opcional: ajuda a IA a escrever a legenda do post)</small></label><textarea id="detalhes" maxlength="1000"></textarea>
  <div class="duas">
    <div><label for="instagram">Instagram</label><input type="text" id="instagram" placeholder="@seunegocio"></div>
    <div><label for="trilha">Trilha</label><select id="trilha"><option value="auto">🤖 A IA escolhe</option><option value="nenhuma">🔇 Sem trilha</option><option value="elegante">✨ Elegante</option><option value="animado">🎉 Animado</option><option value="urgente">⚡ Urgente</option><option value="emocional">💛 Emocional</option><option value="calmo">🌿 Calmo</option><option value="tropical">🌴 Tropical</option><option value="latino">💃 Latino</option><option value="chill">😎 Chill</option></select></div>
  </div>
  <label>Cor de destaque <small>(topo, palavra acesa, cartão)</small></label><div class="corlinha"><input type="color" id="cor" value="#c9a227"><label style="margin:0;font-weight:500"><input type="checkbox" id="cor-ia" checked> a IA escolhe</label></div>
  <div class="chks">
    <label><input type="checkbox" id="cortar_pausas" checked><span>Cortar as pausas<small>silêncio maior que meio segundo</small></span></label>
    <label><input type="checkbox" id="cortar_vicios" checked><span>Cortar os vícios<small>"né", "é", "ãh", "tipo"...</small></span></label>
    <label><input type="checkbox" id="legendas" checked><span>Legenda animada<small>a palavra falada acende</small></span></label>
    <label><input type="checkbox" id="cartao_final" checked><span>Cartão final<small>marca, chamada e @</small></span></label>
  </div>
  <p class="erro" id="erro" role="alert"></p>
  <button class="btn" type="submit" id="enviar" style="width:100%;margin-top:16px">✂️ Editar o meu Reel</button>
</form></div>
<script>
(function () {
  var el = function (s) { return document.querySelector(s); };
  var VIDEO = '', enviando = false;
  function envia(arq) {
    if (arq.size > 120e6) { el('#info').textContent = '⚠️ Vídeo maior que 120 MB.'; return; }
    el('#prev').src = URL.createObjectURL(arq); el('#prev').hidden = false;
    var fd = new FormData(); fd.append('video', arq, arq.name || 'video.mp4');
    var x = new XMLHttpRequest(); x.open('POST', 'editor-reel-video');
    enviando = true; VIDEO = ''; el('#barra').hidden = false; el('#info').textContent = 'Enviando…';
    x.upload.onprogress = function (e) { if (e.lengthComputable) { var p = Math.round(e.loaded / e.total * 100); el('#barra i').style.width = p + '%'; el('#info').textContent = 'Enviando ' + p + '%' + (p === 100 ? ' · guardando…' : ''); } };
    x.onload = function () { enviando = false; var r = {}; try { r = JSON.parse(x.responseText); } catch (e) {}
      if (x.status === 200 && r.ok) { VIDEO = r.id; el('#info').innerHTML = '<span class="ok">✅ Vídeo pronto para editar</span> (' + Math.round(arq.size / 1e6) + ' MB)'; }
      else el('#info').textContent = '⚠️ ' + (r.erro || 'não deu para enviar'); };
    x.onerror = function () { enviando = false; el('#info').textContent = '⚠️ falha de conexão'; };
    x.send(fd);
  }
  var drop = el('#drop'), inp = el('#arq');
  drop.addEventListener('click', function () { inp.click(); });
  ['dragover', 'dragenter'].forEach(function (t) { drop.addEventListener(t, function (e) { e.preventDefault(); drop.classList.add('on'); }); });
  ['dragleave', 'drop'].forEach(function (t) { drop.addEventListener(t, function (e) { e.preventDefault(); drop.classList.remove('on'); }); });
  drop.addEventListener('drop', function (e) { if (e.dataTransfer.files.length) envia(e.dataTransfer.files[0]); });
  inp.addEventListener('change', function () { if (inp.files.length) envia(inp.files[0]); inp.value = ''; });
  el('#ex').addEventListener('click', function () {
    VIDEO = 'exemplo'; el('#prev').src = 'https://files.catbox.moe/gx64ow.mp4'; el('#prev').hidden = false; el('#barra').hidden = true;
    el('#info').innerHTML = '<span class="ok">✅ Vídeo de exemplo</span> (40 s com pausas e "né, é" para cortar)';
    el('#tipo').value = 'imovel'; el('#marca').value = 'Vista Alta Imóveis'; el('#titulo').value = 'Apartamento 3 quartos com varanda gourmet';
    el('#instagram').value = '@vistaalta.imoveis'; el('#detalhes').value = '3 quartos (1 suíte), sala ampla com janelas do chão ao teto, varanda gourmet com churrasqueira e vista para a cidade.';
  });
  el('#form').addEventListener('submit', function (e) {
    e.preventDefault(); el('#erro').textContent = '';
    if (enviando) { el('#erro').textContent = 'Espere o vídeo terminar de enviar.'; return; }
    if (!VIDEO) { el('#erro').textContent = 'Envie o vídeo (ou use o exemplo).'; return; }
    var d = { video: VIDEO };
    ['tipo', 'marca', 'titulo', 'detalhes', 'instagram', 'trilha'].forEach(function (c) { d[c] = el('#' + c).value; });
    ['cortar_pausas', 'cortar_vicios', 'legendas', 'cartao_final'].forEach(function (c) { d[c] = el('#' + c).checked; });
    if (!el('#cor-ia').checked) d.cor = el('#cor').value;
    var bt = el('#enviar'); bt.disabled = true; bt.textContent = 'Começando…';
    fetch('editor-reel', { method: 'POST', headers: { 'Content-Type': 'text/plain' }, body: JSON.stringify(d) }).then(function (r) { return r.json(); }).then(function (r) {
      if (!r.ok) { el('#erro').textContent = (r.erros || ['Não deu para começar.']).join(' '); bt.disabled = false; bt.textContent = '✂️ Editar o meu Reel'; return; }
      location.href = r.link;
    }).catch(function () { el('#erro').textContent = 'Falha de conexão.'; bt.disabled = false; bt.textContent = '✂️ Editar o meu Reel'; });
  });
})();
</script></body></html>
